create table if not exists public.site_profile(id bigint primary key default 1 check(id=1),site_name text not null default 'Knight Hub',bio text not null default 'Texture packs, launchers, codes & socials.',avatar_url text);insert into public.site_profile(id) values(1) on conflict(id) do nothing;create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,is_admin boolean not null default false);create table if not exists public.sections(id bigint generated by default as identity primary key,title text not null,icon text default '🔗',sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());create table if not exists public.links(id bigint generated by default as identity primary key,section_id bigint not null references public.sections(id) on delete cascade,title text not null,description text default '',url text not null,icon text default '🔗',sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $f$ select exists(select 1 from public.profiles where id=auth.uid() and is_admin=true); $f$;alter table public.site_profile enable row level security;alter table public.profiles enable row level security;alter table public.sections enable row level security;alter table public.links enable row level security;drop policy if exists "Public can read profile" on public.site_profile;drop policy if exists "Admins manage profile" on public.site_profile;drop policy if exists "Users can read own profile" on public.profiles;drop policy if exists "Public can read active sections" on public.sections;drop policy if exists "Admins manage sections" on public.sections;drop policy if exists "Public can read active links" on public.links;drop policy if exists "Admins manage links" on public.links;create policy "Public can read profile" on public.site_profile for select to anon,authenticated using(true);create policy "Admins manage profile" on public.site_profile for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "Users can read own profile" on public.profiles for select to authenticated using(auth.uid()=id);create policy "Public can read active sections" on public.sections for select to anon,authenticated using(active=true or public.is_admin());create policy "Admins manage sections" on public.sections for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "Public can read active links" on public.links for select to anon,authenticated using(active=true or public.is_admin());create policy "Admins manage links" on public.links for all to authenticated using(public.is_admin());insert into public.sections(title,icon,sort_order) select 'Social','🌐',1 where not exists(select 1 from public.sections where title='Social');insert into public.sections(title,icon,sort_order) select 'Texture Packs','🧱',2 where not exists(select 1 from public.sections where title='Texture Packs');insert into public.sections(title,icon,sort_order) select 'Launchers','🚀',3 where not exists(select 1 from public.sections where title='Launchers');insert into public.sections(title,icon,sort_order) select 'Codes','💻',4 where not exists(select 1 from public.sections where title='Codes');-- Then add your Auth user's UUID: insert into public.profiles(id,email,is_admin) values('YOUR-UUID','YOUR-EMAIL',true) on conflict(id) do update set is_admin=true,email=excluded.email;